# ---------------- Parquet write options (write with engine, read back with the same engine)
def wr(name, fn, read_opts=None):
    path = f"{WD}/{name}"
    fn(path)
    r = spark.read
    if read_opts:
        for k, v in read_opts.items(): r = r.option(k, v)
    return r.parquet(path)
